ALTER TABLE public.patient_registration_requests ADD COLUMN IF NOT EXISTS original_data JSONB, ADD COLUMN IF NOT EXISTS reviewed_data JSONB;

UPDATE public.patient_registration_requests r SET original_data=jsonb_strip_nulls(to_jsonb(r)-ARRAY['original_data','reviewed_data','account_id','link_id','status','patient_id','reviewed_by','rejection_reason']), reviewed_data=jsonb_strip_nulls(to_jsonb(r)-ARRAY['original_data','reviewed_data','account_id','link_id','status','patient_id','reviewed_by','rejection_reason']) WHERE original_data IS NULL OR reviewed_data IS NULL;

CREATE OR REPLACE FUNCTION public.submit_patient_registration(_token_hash TEXT,_bucket_key TEXT,_payload JSONB) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE target_link public.patient_registration_links%ROWTYPE; request_id UUID; limiter public.patient_registration_rate_limits%ROWTYPE; stored_payload JSONB;
BEGIN
 IF char_length(_token_hash)<>64 OR char_length(_bucket_key)<>64 THEN RAISE EXCEPTION 'Este link não está mais disponível.'; END IF;
 SELECT * INTO target_link FROM public.patient_registration_links WHERE token_hash=_token_hash FOR UPDATE;
 IF NOT FOUND OR target_link.revoked_at IS NOT NULL OR target_link.expires_at<=now() OR target_link.uses_count>=target_link.max_uses THEN RAISE EXCEPTION 'Este link não está mais disponível.'; END IF;
 SELECT * INTO limiter FROM public.patient_registration_rate_limits WHERE bucket_key=_bucket_key FOR UPDATE;
 IF FOUND AND limiter.window_started_at>now()-interval '1 hour' AND limiter.attempts>=10 THEN RAISE EXCEPTION 'Muitas tentativas. Aguarde antes de tentar novamente.'; END IF;
 IF NOT FOUND OR limiter.window_started_at<=now()-interval '1 hour' THEN INSERT INTO public.patient_registration_rate_limits(bucket_key,window_started_at,attempts) VALUES(_bucket_key,now(),1) ON CONFLICT(bucket_key) DO UPDATE SET window_started_at=now(),attempts=1,updated_at=now(); ELSE UPDATE public.patient_registration_rate_limits SET attempts=attempts+1,updated_at=now() WHERE bucket_key=_bucket_key; END IF;
 stored_payload:=_payload-'privacy_consent';
 INSERT INTO public.patient_registration_requests(account_id,link_id,full_name,email,birth_date,cpf,age_group,gender,marital_status,education,occupation,phone,postal_code,street,address_number,address_complement,neighborhood,city,state,guardian_name,guardian_relationship,guardian_phone,guardian_email,emergency_name,emergency_relationship,emergency_phone,emergency_notes,therapy_reason,previous_therapy,previous_therapy_details,medical_diagnosis,medical_diagnosis_details,medication_use,medication_details,family_mental_health,family_mental_health_details,payment_preference,referral_source,referral_source_other,privacy_consent_at,original_data,reviewed_data)
 VALUES(target_link.account_id,target_link.id,BTRIM(_payload->>'full_name'),lower(BTRIM(_payload->>'email')),(_payload->>'birth_date')::date,regexp_replace(_payload->>'cpf','\D','','g'),(_payload->>'age_group')::public.age_group,NULLIF(BTRIM(_payload->>'gender'),''),NULLIF(BTRIM(_payload->>'marital_status'),''),NULLIF(BTRIM(_payload->>'education'),''),NULLIF(BTRIM(_payload->>'occupation'),''),NULLIF(BTRIM(_payload->>'phone'),''),regexp_replace(_payload->>'postal_code','\D','','g'),NULLIF(BTRIM(_payload->>'street'),''),NULLIF(BTRIM(_payload->>'address_number'),''),NULLIF(BTRIM(_payload->>'address_complement'),''),NULLIF(BTRIM(_payload->>'neighborhood'),''),BTRIM(_payload->>'city'),upper(BTRIM(_payload->>'state')),NULLIF(BTRIM(_payload->>'guardian_name'),''),NULLIF(BTRIM(_payload->>'guardian_relationship'),''),NULLIF(BTRIM(_payload->>'guardian_phone'),''),NULLIF(lower(BTRIM(_payload->>'guardian_email')),''),NULLIF(BTRIM(_payload->>'emergency_name'),''),NULLIF(BTRIM(_payload->>'emergency_relationship'),''),NULLIF(BTRIM(_payload->>'emergency_phone'),''),NULLIF(BTRIM(_payload->>'emergency_notes'),''),BTRIM(_payload->>'therapy_reason'),_payload->>'previous_therapy',NULLIF(BTRIM(_payload->>'previous_therapy_details'),''),_payload->>'medical_diagnosis',NULLIF(BTRIM(_payload->>'medical_diagnosis_details'),''),_payload->>'medication_use',NULLIF(BTRIM(_payload->>'medication_details'),''),_payload->>'family_mental_health',NULLIF(BTRIM(_payload->>'family_mental_health_details'),''),NULLIF(_payload->>'payment_preference',''),NULLIF(_payload->>'referral_source',''),NULLIF(BTRIM(_payload->>'referral_source_other'),''),now(),stored_payload,stored_payload) RETURNING id INTO request_id;
 UPDATE public.patient_registration_links SET uses_count=uses_count+1 WHERE id=target_link.id;
 INSERT INTO public.audit_events(account_id,actor_user_id,entity_type,entity_id,action,changed_fields) VALUES(target_link.account_id,NULL,'patient_registration',request_id,'submitted',ARRAY['status']);
 RETURN request_id;
END;$$;
REVOKE ALL ON FUNCTION public.submit_patient_registration(TEXT,TEXT,JSONB) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.submit_patient_registration(TEXT,TEXT,JSONB) TO service_role;

CREATE OR REPLACE FUNCTION public.save_patient_registration_review(_request_id UUID,_payload JSONB) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE target_request public.patient_registration_requests%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sessão inválida.'; END IF;
 SELECT * INTO target_request FROM public.patient_registration_requests WHERE id=_request_id FOR UPDATE;
 IF NOT FOUND OR NOT public.is_account_member(target_request.account_id) THEN RAISE EXCEPTION 'Solicitação não encontrada.'; END IF;
 IF target_request.status<>'awaiting_approval' THEN RAISE EXCEPTION 'Esta solicitação já foi revisada.'; END IF;
 IF NULLIF(BTRIM(_payload->>'full_name'),'') IS NULL OR NULLIF(_payload->>'birth_date','') IS NULL OR NULLIF(BTRIM(_payload->>'email'),'') IS NULL OR NULLIF(BTRIM(_payload->>'cpf'),'') IS NULL OR NULLIF(BTRIM(_payload->>'postal_code'),'') IS NULL OR NULLIF(BTRIM(_payload->>'city'),'') IS NULL OR char_length(BTRIM(COALESCE(_payload->>'state','')))<>2 OR NULLIF(BTRIM(_payload->>'therapy_reason'),'') IS NULL THEN RAISE EXCEPTION 'Revise os campos obrigatórios do cadastro.'; END IF;
 UPDATE public.patient_registration_requests SET full_name=BTRIM(_payload->>'full_name'),email=lower(BTRIM(_payload->>'email')),birth_date=(_payload->>'birth_date')::date,cpf=regexp_replace(_payload->>'cpf','\D','','g'),age_group=(_payload->>'age_group')::public.age_group,gender=NULLIF(BTRIM(_payload->>'gender'),''),marital_status=NULLIF(BTRIM(_payload->>'marital_status'),''),education=NULLIF(BTRIM(_payload->>'education'),''),occupation=NULLIF(BTRIM(_payload->>'occupation'),''),phone=NULLIF(BTRIM(_payload->>'phone'),''),postal_code=regexp_replace(_payload->>'postal_code','\D','','g'),street=NULLIF(BTRIM(_payload->>'street'),''),address_number=NULLIF(BTRIM(_payload->>'address_number'),''),address_complement=NULLIF(BTRIM(_payload->>'address_complement'),''),neighborhood=NULLIF(BTRIM(_payload->>'neighborhood'),''),city=BTRIM(_payload->>'city'),state=upper(BTRIM(_payload->>'state')),guardian_name=NULLIF(BTRIM(_payload->>'guardian_name'),''),guardian_relationship=NULLIF(BTRIM(_payload->>'guardian_relationship'),''),guardian_phone=NULLIF(BTRIM(_payload->>'guardian_phone'),''),guardian_email=NULLIF(lower(BTRIM(_payload->>'guardian_email')),''),emergency_name=NULLIF(BTRIM(_payload->>'emergency_name'),''),emergency_relationship=NULLIF(BTRIM(_payload->>'emergency_relationship'),''),emergency_phone=NULLIF(BTRIM(_payload->>'emergency_phone'),''),emergency_notes=NULLIF(BTRIM(_payload->>'emergency_notes'),''),therapy_reason=BTRIM(_payload->>'therapy_reason'),previous_therapy=_payload->>'previous_therapy',previous_therapy_details=NULLIF(BTRIM(_payload->>'previous_therapy_details'),''),medical_diagnosis=_payload->>'medical_diagnosis',medical_diagnosis_details=NULLIF(BTRIM(_payload->>'medical_diagnosis_details'),''),medication_use=_payload->>'medication_use',medication_details=NULLIF(BTRIM(_payload->>'medication_details'),''),family_mental_health=_payload->>'family_mental_health',family_mental_health_details=NULLIF(BTRIM(_payload->>'family_mental_health_details'),''),payment_preference=NULLIF(_payload->>'payment_preference',''),referral_source=NULLIF(_payload->>'referral_source',''),referral_source_other=NULLIF(BTRIM(_payload->>'referral_source_other'),''),reviewed_data=_payload,reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() WHERE id=_request_id;
 INSERT INTO public.audit_events(account_id,actor_user_id,entity_type,entity_id,action,changed_fields) VALUES(target_request.account_id,auth.uid(),'patient_registration',_request_id,'review_updated',ARRAY['reviewed_data']);
 RETURN _request_id;
END;$$;
REVOKE ALL ON FUNCTION public.save_patient_registration_review(UUID,JSONB) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_patient_registration_review(UUID,JSONB) TO authenticated,service_role;
REVOKE UPDATE ON public.patient_registration_requests FROM authenticated;

CREATE OR REPLACE FUNCTION public.approve_patient_registration(_request_id UUID,_existing_patient_id UUID DEFAULT NULL) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE target_request public.patient_registration_requests%ROWTYPE; result_patient_id UUID; owner_user_id UUID; duplicate_count INTEGER; intake JSONB; chosen_is_match BOOLEAN;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sessão inválida.'; END IF;
 SELECT * INTO target_request FROM public.patient_registration_requests WHERE id=_request_id FOR UPDATE;
 IF NOT FOUND OR NOT public.is_account_member(target_request.account_id) THEN RAISE EXCEPTION 'Solicitação não encontrada.'; END IF;
 IF target_request.status='approved' AND target_request.patient_id IS NOT NULL THEN RETURN target_request.patient_id; END IF;
 IF target_request.status<>'awaiting_approval' THEN RAISE EXCEPTION 'Esta solicitação já foi revisada.'; END IF;
 SELECT a.owner_user_id INTO owner_user_id FROM public.accounts a WHERE a.id=target_request.account_id;
 SELECT count(*) INTO duplicate_count FROM public.patients p WHERE p.account_id=target_request.account_id AND (regexp_replace(COALESCE(p.cpf,''),'\D','','g')=regexp_replace(target_request.cpf,'\D','','g') OR (p.email IS NOT NULL AND lower(p.email)=lower(target_request.email)) OR (lower(p.full_name)=lower(target_request.full_name) AND p.birth_date=target_request.birth_date));
 IF _existing_patient_id IS NULL AND duplicate_count>0 THEN RAISE EXCEPTION 'Já encontramos um cadastro semelhante. Revise antes de aprovar.'; END IF;
 IF _existing_patient_id IS NOT NULL THEN
  SELECT EXISTS(SELECT 1 FROM public.patients p WHERE p.id=_existing_patient_id AND p.account_id=target_request.account_id AND (regexp_replace(COALESCE(p.cpf,''),'\D','','g')=regexp_replace(target_request.cpf,'\D','','g') OR (p.email IS NOT NULL AND lower(p.email)=lower(target_request.email)) OR (lower(p.full_name)=lower(target_request.full_name) AND p.birth_date=target_request.birth_date))) INTO chosen_is_match;
  IF NOT chosen_is_match THEN RAISE EXCEPTION 'O paciente escolhido não corresponde às duplicidades encontradas.'; END IF;
  SELECT p.id INTO result_patient_id FROM public.patients p WHERE p.id=_existing_patient_id AND p.account_id=target_request.account_id FOR UPDATE;
  UPDATE public.patients p SET birth_date=COALESCE(target_request.birth_date,p.birth_date),gender=COALESCE(NULLIF(target_request.gender,''),p.gender),phone=COALESCE(NULLIF(target_request.phone,''),p.phone),email=COALESCE(NULLIF(target_request.email,''),p.email),address=COALESCE(NULLIF(concat_ws(', ',NULLIF(target_request.street,''),NULLIF(target_request.address_number,''),NULLIF(target_request.address_complement,''),NULLIF(target_request.neighborhood,'')),''),p.address),street=COALESCE(NULLIF(target_request.street,''),p.street),city=COALESCE(NULLIF(target_request.city,''),p.city),state=COALESCE(NULLIF(target_request.state,''),p.state),cpf=COALESCE(NULLIF(target_request.cpf,''),p.cpf),postal_code=COALESCE(NULLIF(target_request.postal_code,''),p.postal_code),address_number=COALESCE(NULLIF(target_request.address_number,''),p.address_number),address_complement=COALESCE(NULLIF(target_request.address_complement,''),p.address_complement),neighborhood=COALESCE(NULLIF(target_request.neighborhood,''),p.neighborhood),marital_status=COALESCE(NULLIF(target_request.marital_status,''),p.marital_status),education=COALESCE(NULLIF(target_request.education,''),p.education),occupation=COALESCE(NULLIF(target_request.occupation,''),p.occupation) WHERE p.id=result_patient_id;
 ELSE
  INSERT INTO public.patients(account_id,user_id,full_name,age_group,birth_date,gender,phone,email,address,street,city,state,status,cpf,postal_code,address_number,address_complement,neighborhood,marital_status,education,occupation,registration_source) VALUES(target_request.account_id,owner_user_id,target_request.full_name,target_request.age_group,target_request.birth_date,target_request.gender,target_request.phone,target_request.email,concat_ws(', ',NULLIF(target_request.street,''),NULLIF(target_request.address_number,''),NULLIF(target_request.address_complement,''),NULLIF(target_request.neighborhood,'')),target_request.street,target_request.city,target_request.state,'avaliacao',target_request.cpf,target_request.postal_code,target_request.address_number,target_request.address_complement,target_request.neighborhood,target_request.marital_status,target_request.education,target_request.occupation,'pre_registration_link') RETURNING id INTO result_patient_id;
 END IF;
 IF target_request.age_group<>'adulto' AND target_request.guardian_name IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.guardians g WHERE g.patient_id=result_patient_id AND g.account_id=target_request.account_id) THEN INSERT INTO public.guardians(account_id,user_id,patient_id,full_name,relationship,phone,email,is_primary) VALUES(target_request.account_id,owner_user_id,result_patient_id,target_request.guardian_name,target_request.guardian_relationship,target_request.guardian_phone,target_request.guardian_email,true); END IF;
 intake:=jsonb_build_object('motivo_busca',target_request.therapy_reason,'terapia_anterior',target_request.previous_therapy,'detalhes_terapia_anterior',target_request.previous_therapy_details,'diagnostico_medico',target_request.medical_diagnosis,'detalhes_diagnostico',target_request.medical_diagnosis_details,'uso_medicamento',target_request.medication_use,'detalhes_medicamento',target_request.medication_details,'historico_familiar_saude_mental',target_request.family_mental_health,'detalhes_historico_familiar',target_request.family_mental_health_details,'contato_emergencia',jsonb_build_object('nome',target_request.emergency_name,'vinculo',target_request.emergency_relationship,'telefone',target_request.emergency_phone,'observacao',target_request.emergency_notes),'preferencia_pagamento',target_request.payment_preference,'origem',target_request.referral_source,'origem_outro',target_request.referral_source_other);
 IF NOT EXISTS(SELECT 1 FROM public.anamneses a WHERE a.patient_id=result_patient_id AND a.account_id=target_request.account_id AND a.template_key='pre_registration') THEN INSERT INTO public.anamneses(account_id,user_id,patient_id,title,template_key,content,is_completed) VALUES(target_request.account_id,owner_user_id,result_patient_id,'Informações do pré-cadastro','pre_registration',intake,true); END IF;
 UPDATE public.patient_registration_requests SET status='approved',patient_id=result_patient_id,reviewed_by=auth.uid(),reviewed_at=COALESCE(reviewed_at,now()),approved_at=now(),rejection_reason=NULL,updated_at=now() WHERE id=_request_id;
 INSERT INTO public.audit_events(account_id,actor_user_id,entity_type,entity_id,action,changed_fields) VALUES(target_request.account_id,auth.uid(),'patient_registration',_request_id,'approved',ARRAY['status','patient_id']);
 RETURN result_patient_id;
END;$$;
REVOKE ALL ON FUNCTION public.approve_patient_registration(UUID,UUID) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.approve_patient_registration(UUID,UUID) TO authenticated,service_role;

CREATE OR REPLACE FUNCTION public.reject_patient_registration(_request_id UUID,_reason TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE target_request public.patient_registration_requests%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sessão inválida.'; END IF;
 SELECT * INTO target_request FROM public.patient_registration_requests WHERE id=_request_id FOR UPDATE;
 IF NOT FOUND OR NOT public.is_account_member(target_request.account_id) THEN RAISE EXCEPTION 'Solicitação não encontrada.'; END IF;
 IF target_request.status<>'awaiting_approval' THEN RAISE EXCEPTION 'Esta solicitação já foi revisada.'; END IF;
 IF char_length(BTRIM(COALESCE(_reason,'')))<3 THEN RAISE EXCEPTION 'Informe o motivo da recusa.'; END IF;
 UPDATE public.patient_registration_requests SET status='rejected',reviewed_by=auth.uid(),reviewed_at=now(),rejected_at=now(),rejection_reason=BTRIM(_reason),updated_at=now() WHERE id=_request_id;
 INSERT INTO public.audit_events(account_id,actor_user_id,entity_type,entity_id,action,changed_fields) VALUES(target_request.account_id,auth.uid(),'patient_registration',_request_id,'rejected',ARRAY['status','rejection_reason']);
END;$$;
REVOKE ALL ON FUNCTION public.reject_patient_registration(UUID,TEXT) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.reject_patient_registration(UUID,TEXT) TO authenticated,service_role;